codeExamples.java:
import java.util.ArrayList;
public class Main {
    public static void main(String[] args) {
        ArrayList<Integer> numbers = new ArrayList<>();
        numbers.add(10); numbers.add(20); numbers.add(30);
        int firstItem = numbers.get(0);
        System.out.println("First: " + firstItem + ", Size: " + numbers.size());
    }
}

codeExamples.javascript:
let numbers = [10, 20, 30, 40, 50];
numbers.push(60);
let firstItem = numbers[0];
let subSlice = numbers.slice(1, 4);
console.log(`First: ${firstItem}, Slice: ${subSlice}, Full Array: ${numbers}`);

codeExamples.cpp:
#include <iostream>
#include <vector>
int main() {
    std::vector<int> numbers = {10, 20, 30, 40, 50};
    numbers.push_back(60);
    std::cout << "First: " << numbers[0] << ", Size: " << numbers.size() << std::endl;
    return 0;
}
